// src/App.jsx — Main router for Agro Zenith
import { useState } from "react";
import C from "./constants/colors";
import S from "./utils/storage";
import T from "./constants/translates";
// Layout
import Sidebar from "./components/layout/Sidebar";

// Pages
import AuthPage          from "./pages/AuthPage";
import Dashboard         from "./pages/Dashboard";
import AgroBot           from "./pages/AgroBot";
import DiseaseDetection  from "./pages/DiseaseDetection";
import FarmMap           from "./pages/FarmMap";
import MarketPrices      from "./pages/MarketPrices";
import Community         from "./pages/Community";
import Schemes           from "./pages/Schemes";
import Shops             from "./pages/Shops";
import Profile           from "./pages/Profile";

export default function App() {
  // ── Auth state ─────────────────────────────────────────────────────────────
  const [user, setUser] = useState(() => S.get("current_user") || null);

  // 2. Language state
  const [lang, setLang] = useState("en");

  // 3. Navigation state (ONLY ONE OF THESE)
  const [page, setPage] = useState("dashboard");

  // 4. Translation Helper
  const t = (path) => {
    try {
      return path.split('.').reduce((obj, key) => obj[key], T[lang]) || path;
    } catch (e) {
      return path;
    }
  };
  return(
    <div className="flex h-screen bg-gray-100">
      {/* Sidebar */}
      <div className="w-64 bg-green-900 text-white p-4 flex flex-col">
        <h1 className="text-xl font-bold mb-8">Agro Zenith</h1>

        {/* Language Toggle Button */}
        <button 
          onClick={() => setLang(lang === 'en' ? 'ta' : 'en')}
          className="mb-6 p-2 bg-green-700 hover:bg-green-600 rounded text-xs font-bold uppercase transition-all"
        >
          {lang === 'en' ? 'Change to தமிழ்' : 'English-க்கு மாற்றவும்'}
        </button>

        <nav className="flex-1 space-y-2">
          <button onClick={() => setPage("dashboard")} className={`w-full text-left p-2 rounded ${page === 'dashboard' ? 'bg-green-700' : ''}`}>Dashboard</button>
          {/* Add other nav items here */}
        </nav>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-auto">
        {page === "dashboard" && <Dashboard user={user} t={t} />}
      </div>
    </div>
  )

  const translations = {
  en: { welcome: "Welcome", alerts: "Active Farm Alerts", risk: "Risk Analysis", market: "Today's Market" },
  ta: { welcome: "வணக்கம்", alerts: "பண்ணை எச்சரிக்கைகள்", risk: "ஆபத்து பகுப்பாய்வு", market: "சந்தை நிலவரம்" },
  hi: { welcome: "नमस्ते", alerts: "कृषि अलर्ट", risk: "जोखिम विश्लेषण", market: "आज का बाजार" }
};

  // ── Handlers ───────────────────────────────────────────────────────────────
  const handleLogin  = (u) => { setUser(u); setPage("dashboard"); };
  const handleLogout = ()  => { S.del("current_user"); setUser(null); setPage("dashboard"); };
  const handleUpdate = (u) => { setUser(u); };

  // ── Not logged in → show Auth ──────────────────────────────────────────────
  if (!user) return <AuthPage onLogin={handleLogin} />;

  // ── Page map ───────────────────────────────────────────────────────────────
  const pages = {
    dashboard: <Dashboard        user={user}  setPage={setPage} t={t} />,
    bot:       <AgroBot          user={user} t={t} />,
    disease:   <DiseaseDetection user={user} t={t} />,
    map:       <FarmMap          user={user} t={t} />,
    market:    <MarketPrices t={t} />,
    community: <Community        user={user} t={t} />,
    schemes:   <Schemes          user={user} t={t} />,
    shops:     <Shops t={t} />,
    profile:   <Profile
                  user={user} t={t}
                  onLogout={handleLogout}
                  onUpdate={handleUpdate}
               />,
  };

  // ── Shell layout ───────────────────────────────────────────────────────────
  return (
    <div style={{
      display:             "flex",
      minHeight:           "100vh",
      background:          C.bg,
      fontFamily:          "'Inter','Segoe UI',system-ui,-apple-system,sans-serif",
      fontSize:            14,
      color:               C.text,
      WebkitFontSmoothing: "antialiased",
    }}>
      {/* Pass lang and setLang to Sidebar */}
      <Sidebar user={user} page={page} setPage={setPage} lang={lang} setLang={setLang} t={t} />
      {/* Main content — scrollable */}
      <div style={{ flex: 1, overflowY: "auto", minWidth: 0, maxHeight: "100vh" }}>
        {pages[page] || pages.dashboard}
      </div>
    </div>
  );
}
